FONT = "Times New Roman"

def smart(s):
    out = []
    for i, ch in enumerate(s):
        prev = s[i-1] if i > 0 else " "
        if ch == "\"":
            out.append("“" if prev in " (\t[—/" else "”")
        elif ch == "'"'"'":
            out.append("‘" if prev in " (\t[—" else "’")
        else:
            out.append(ch)
    return "".join(out)

TOK = re.compile(r"(\*\*.+?\*\*|__.+?__|\*.+?\*)")

def add_runs(p, text, size=11, base_bold=False):
    for part in TOK.split(text):
        if not part:
            continue
        b, it, u = base_bold, False, False
        if part.startswith("**"):
            part, b = part[2:-2], True
        elif part.startswith("__"):
            part, b, u = part[2:-2], True, True
        elif part.startswith("*"):
            part, it = part[1:-1], True
        r = p.add_run(smart(part))
