            para(d, body, indent=0.5)
        elif tag == "I2":
            para(d, body, indent=1.0)
        elif tag == "L":
            para(d, body, "L", after=2)
        elif tag == "PB":
            page_break(d)
        else:
            raise ValueError(raw)
